import { describe, expect, it } from "vitest";
import { createApp, type App } from "../src/app.ts";

const NOW = new Date("2026-10-01T08:00:00Z");
const fixedClock = () => NOW;

const newApp = (): App => createApp({ clock: fixedClock });

interface CouponOverrides {
  code?: string;
  type?: "FIXED" | "PERCENT";
  value?: number;
  minAmountCents?: number;
  maxDiscountCents?: number | null;
  validFrom?: string;
  validUntil?: string;
  status?: "ACTIVE" | "DISABLED";
  usageLimit?: number | null;
}

function createCoupon(app: App, overrides: CouponOverrides = {}): void {
  const res = app.request("POST", "/coupons", {
    code: "SAVE20",
    type: "PERCENT",
    value: 20,
    minAmountCents: 0,
    maxDiscountCents: null,
    validFrom: "2026-01-01T00:00:00Z",
    validUntil: "2027-01-01T00:00:00Z",
    status: "ACTIVE",
    usageLimit: null,
    ...overrides,
  });
  expect(res.status).toBe(201);
}

function createOrder(app: App, amountCents: number): number {
  const res = app.request("POST", "/orders", { customer: "alice", amountCents });
  expect(res.status).toBe(201);
  return (res.body as { id: number }).id;
}

function apply(app: App, orderId: number, couponCode: unknown) {
  return app.request("POST", `/orders/${orderId}/apply-coupon`, { couponCode });
}

function expectError(res: { status: number; body: unknown }, status: number, code: string) {
  expect(res.status).toBe(status);
  expect((res.body as any).error.code).toBe(code);
}

describe("apply coupon - discount calculation", () => {
  it("AC-01: PERCENT computes floor(amount * value / 100)", () => {
    const app = newApp();
    createCoupon(app, { type: "PERCENT", value: 20 });
    const orderId = createOrder(app, 10000);
    const res = apply(app, orderId, "SAVE20");
    expect(res.status).toBe(200);
    expect(res.body).toMatchObject({ discountCents: 2000, finalAmountCents: 8000, couponCode: "SAVE20" });
  });

  it("AC-02: FIXED subtracts its value", () => {
    const app = newApp();
    createCoupon(app, { type: "FIXED", value: 1500 });
    const orderId = createOrder(app, 10000);
    const res = apply(app, orderId, "SAVE20");
    expect(res.body).toMatchObject({ discountCents: 1500, finalAmountCents: 8500 });
  });

  it("AC-03: maxDiscountCents caps a PERCENT discount", () => {
    const app = newApp();
    createCoupon(app, { type: "PERCENT", value: 20, maxDiscountCents: 5000 });
    const orderId = createOrder(app, 100000);
    const res = apply(app, orderId, "SAVE20");
    expect(res.body).toMatchObject({ discountCents: 5000 });
  });

  it("AC-05: PERCENT rounds down", () => {
    const app = newApp();
    createCoupon(app, { type: "PERCENT", value: 15 });
    const orderId = createOrder(app, 999);
    const res = apply(app, orderId, "SAVE20");
    expect(res.body).toMatchObject({ discountCents: 149 });
  });

  it("AC-04: discount never exceeds the order amount", () => {
    const app = newApp();
    createCoupon(app, { type: "FIXED", value: 3000 });
    const orderId = createOrder(app, 1000);
    const res = apply(app, orderId, "SAVE20");
    expect(res.body).toMatchObject({ discountCents: 1000, finalAmountCents: 0 });
  });

  it("AC-06: amount equal to minAmountCents is allowed", () => {
    const app = newApp();
    createCoupon(app, { minAmountCents: 5000 });
    const orderId = createOrder(app, 5000);
    const res = apply(app, orderId, "SAVE20");
    expect(res.status).toBe(200);
  });
});

describe("apply coupon - validity window", () => {
  it("AC-07: now == validFrom is accepted", () => {
    const app = newApp();
    createCoupon(app, { validFrom: NOW.toISOString(), validUntil: "2027-01-01T00:00:00Z" });
    const orderId = createOrder(app, 10000);
    expect(apply(app, orderId, "SAVE20").status).toBe(200);
  });

  it("AC-07: now == validUntil is expired", () => {
    const app = newApp();
    createCoupon(app, { validFrom: "2026-01-01T00:00:00Z", validUntil: NOW.toISOString() });
    const orderId = createOrder(app, 10000);
    expectError(apply(app, orderId, "SAVE20"), 400, "COUPON_EXPIRED");
  });
});

describe("apply coupon - normalization and response", () => {
  it("AC-10: trims and uppercases the submitted code", () => {
    const app = newApp();
    createCoupon(app, { code: "SAVE20" });
    const orderId = createOrder(app, 10000);
    const res = apply(app, orderId, " save20 ");
    expect(res.status).toBe(200);
    expect((res.body as any).couponCode).toBe("SAVE20");
  });

  it("REQ-14: response equals the subsequent GET /orders/:id", () => {
    const app = newApp();
    createCoupon(app, { code: "SAVE20" });
    const orderId = createOrder(app, 10000);
    const applied = apply(app, orderId, "SAVE20");
    const fetched = app.request("GET", `/orders/${orderId}`);
    expect(applied.status).toBe(200);
    expect(applied.body).toEqual(fetched.body);
  });
});

describe("apply coupon - rejections leave no side effects", () => {
  it("REQ-13: missing, non-string or blank code is INVALID_REQUEST", () => {
    const app = newApp();
    const orderId = createOrder(app, 10000);
    expectError(app.request("POST", `/orders/${orderId}/apply-coupon`, {}), 400, "INVALID_REQUEST");
    expectError(apply(app, orderId, 123), 400, "INVALID_REQUEST");
    expectError(apply(app, orderId, "   "), 400, "INVALID_REQUEST");
  });

  it("unknown order is ORDER_NOT_FOUND", () => {
    const app = newApp();
    expectError(apply(app, 99, "SAVE20"), 404, "ORDER_NOT_FOUND");
  });

  it("non-pending order is ORDER_NOT_PENDING", () => {
    const app = newApp();
    createCoupon(app);
    const orderId = createOrder(app, 10000);
    app.request("POST", `/orders/${orderId}/pay`);
    expectError(apply(app, orderId, "SAVE20"), 409, "ORDER_NOT_PENDING");
  });

  it("unknown coupon is COUPON_NOT_FOUND", () => {
    const app = newApp();
    const orderId = createOrder(app, 10000);
    expectError(apply(app, orderId, "NOPE"), 404, "COUPON_NOT_FOUND");
  });

  it("disabled coupon is COUPON_INACTIVE", () => {
    const app = newApp();
    createCoupon(app, { status: "DISABLED" });
    const orderId = createOrder(app, 10000);
    expectError(apply(app, orderId, "SAVE20"), 400, "COUPON_INACTIVE");
  });

  it("not-yet-valid coupon is COUPON_NOT_YET_VALID", () => {
    const app = newApp();
    createCoupon(app, { validFrom: "2027-01-01T00:00:00Z", validUntil: "2028-01-01T00:00:00Z" });
    const orderId = createOrder(app, 10000);
    expectError(apply(app, orderId, "SAVE20"), 400, "COUPON_NOT_YET_VALID");
  });

  it("exhausted usage is COUPON_USAGE_EXHAUSTED", () => {
    const app = newApp();
    createCoupon(app, { usageLimit: 1 });
    const first = createOrder(app, 10000);
    const second = createOrder(app, 10000);
    expect(apply(app, first, "SAVE20").status).toBe(200);
    expectError(apply(app, second, "SAVE20"), 400, "COUPON_USAGE_EXHAUSTED");
  });

  it("below minimum is MINIMUM_NOT_MET", () => {
    const app = newApp();
    createCoupon(app, { minAmountCents: 5000 });
    const orderId = createOrder(app, 4999);
    expectError(apply(app, orderId, "SAVE20"), 400, "MINIMUM_NOT_MET");
  });

  it("error precedence: order checks precede coupon checks", () => {
    const app = newApp();
    const orderId = createOrder(app, 10000);
    app.request("POST", `/orders/${orderId}/pay`);
    expectError(apply(app, orderId, "DOES-NOT-EXIST"), 409, "ORDER_NOT_PENDING");
  });
});

describe("apply coupon - single use per order and persistence", () => {
  it("AC-08: a second application is rejected and amounts are unchanged", () => {
    const app = newApp();
    createCoupon(app);
    const orderId = createOrder(app, 10000);
    const first = apply(app, orderId, "SAVE20");
    expect(first.status).toBe(200);
    const second = apply(app, orderId, "SAVE20");
    expectError(second, 409, "COUPON_ALREADY_APPLIED");
    expect(app.request("GET", `/orders/${orderId}`).body).toEqual(first.body);
  });

  it("AC-09: usedCount increments and a redemption row is inserted", () => {
    const app = newApp();
    createCoupon(app);
    const orderId = createOrder(app, 10000);
    expect(apply(app, orderId, "SAVE20").status).toBe(200);

    const coupon = app.request("GET", "/coupons/SAVE20").body as { usedCount: number };
    expect(coupon.usedCount).toBe(1);

    const rows = app.db
      .prepare("SELECT * FROM coupon_redemptions WHERE order_id = ?")
      .all(orderId) as unknown as Array<{ order_id: number; coupon_code: string; discount_cents: number; created_at: string }>;
    expect(rows).toHaveLength(1);
    expect(rows[0]).toMatchObject({
      order_id: orderId,
      coupon_code: "SAVE20",
      discount_cents: 2000,
      created_at: NOW.toISOString(),
    });
  });

  it("rejected requests do not change usedCount", () => {
    const app = newApp();
    createCoupon(app, { minAmountCents: 5000 });
    const orderId = createOrder(app, 1000);
    expectError(apply(app, orderId, "SAVE20"), 400, "MINIMUM_NOT_MET");
    expect((app.request("GET", "/coupons/SAVE20").body as { usedCount: number }).usedCount).toBe(0);
  });
});

